
import { useState, useRef, useCallback } from 'react';
import { toast } from 'sonner';

export function useMockInterviewer() {
    const [isLocked, setIsLocked] = useState(false);
    const [question, setQuestion] = useState<string | null>(null);
    const [feedback, setFeedback] = useState<string | null>(null);
    const [isProcessing, setIsProcessing] = useState(false);

    // Limits
    const lastCheckTime = useRef<number>(Date.now());
    const lineCountRef = useRef<number>(0);

    const triggerInterruption = async (code: string) => {
        setIsProcessing(true);
        try {
            const res = await fetch('/api/interview/interrupt', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ type: 'interrupt', code })
            });
            const data = await res.json();

            if (data.trigger) {
                setQuestion(data.question);
                setIsLocked(true);
                toast.warning("INTERRUPTION!", { description: "The interviewer has a question." });
            }
        } catch (e) {
            console.error(e);
        } finally {
            setIsProcessing(false);
        }
    };

    const validateAnswer = async (code: string, answer: string) => {
        setIsProcessing(true);
        try {
            const res = await fetch('/api/interview/interrupt', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    type: 'validate',
                    code,
                    question,
                    answer
                })
            });
            const data = await res.json();

            if (data.correct) {
                toast.success("Good answer.", { description: data.feedback });
                setIsLocked(false);
                setQuestion(null);
                setFeedback(null);
            } else {
                toast.error("Not quite.", { description: data.feedback });
                setFeedback(data.feedback);
                // Remain locked
            }

        } catch (e) {
            console.error(e);
            // Emergency unlock if API fails
            setIsLocked(false);
        } finally {
            setIsProcessing(false);
        }
    };

    // Called by Code Editor onChange
    const onCodeChange = useCallback((value: string | undefined) => {
        if (!value) return;

        const lines = value.split('\n').length;
        const diff = Math.abs(lines - lineCountRef.current);

        // Check condition: Added > 5 lines or total > x is risky logic efficiently
        // Better: Check every 40 lines of TOTAL code written?
        // Or check periodically. User asked "Every 4 mins OR > 40 lines".
        // Let's simplified check: random chance if lines grow?
        // Or strictly: if (lines > lastCheckLines + 40)

        // Strict as per requirement
        /*
        if (lines > lineCountRef.current + 40) {
             lineCountRef.current = lines; // Reset threshold
             triggerInterruption(value);
        }
        */
        // Actually simpler for now, expose manual trigger or timer based in component
        lineCountRef.current = lines;

    }, []);

    // Check time
    // This hook exposes the logic, the Component will run the interval

    return {
        isLocked,
        question,
        feedback,
        isProcessing,
        triggerInterruption,
        validateAnswer,
        onCodeChange
    };
}
